  "spec": {
    "jobTemplate": {
      "spec": {
        "template": {
          "spec": {
            "nodeSelector": {
              "nodepool": "np-zyy-etl"
            },
            "tolerations": [
              {
                "key": "dedicated",
                "operator": "Equal",
                "value": "etl",
                "effect": "NoSchedule"
              }
            ]
          }
        }
      }
    }
  }
}'
